from format_lecon import Lesson,paras,steps,table
from coamoxicilline_iv import coamoxi_iv
l=Lesson('Cellulite orbitaire',7);med=coamoxi_iv(l)
l.add('La {cellulite orbitaire} est une infection des tissus situés derrière le septum orbitaire. Elle menace la vision et peut se compliquer d’une extension intracrânienne. Toute suspicion impose une évaluation hospitalière urgente.',paras('L’infection concerne notamment graisse et muscles orbitaires. Elle se distingue de la cellulite préseptale, limitée aux tissus antérieurs. Les manifestations palpébrales peuvent se ressembler, mais le risque et le traitement diffèrent.', 'Une limitation douloureuse du regard, une diplopie, une exophtalmie ou une baisse visuelle doivent faire suspecter une atteinte profonde. Tous ces signes ne sont pas nécessaires pour agir. Un œil impossible à examiner ne peut pas être déclaré normal.', 'Une collection peut se former sous le périoste ou dans l’orbite. L’absence de collection visible n’annule pas le diagnostic d’infection postseptale ni le besoin de surveillance spécialisée.'),(9,37,43))
l.add('Le {contexte} recherche surtout un foyer voisin et les facteurs de risque. Une sinusite, un traumatisme ou une infection dentaire peut précéder l’atteinte. Le terrain influence les germes, la gravité et le traitement.',paras('Les sinus ethmoïdaux sont proches de l’orbite. Une origine sinusienne est particulièrement importante chez l’enfant. Une porte d’entrée traumatique ou postopératoire et un corps étranger doivent aussi être recherchés.', 'Interroger sur antibiotiques récents, vaccination, immunodépression, diabète et colonisation connue par un germe résistant. Ces éléments orientent les prélèvements et la couverture empirique sans remplacer les données locales.', 'Aucune incidence suisse n’est attribuée à partir des séries étrangères. Les données canadiennes récentes servent à confronter les choix pédiatriques, pas à décrire la résistance en Suisse.', 'Un tableau inhabituel chez une personne immunodéprimée impose d’envisager une infection opportuniste, notamment fongique. Une routine antibiotique bactérienne ne suffit pas à ce contexte.'),(9,37,42,43))
l.add('Les {bases anatomiques} expliquent le danger visuel et neurologique. L’orbite contient des structures fragiles dans un espace peu extensible. L’inflammation, une collection et la propagation veineuse peuvent entraîner des complications rapides.',paras('La lame papyracée sépare les cellules ethmoïdales de l’orbite. Une infection peut atteindre l’espace sous-périosté puis les tissus orbitaires. Le septum marque la limite avec l’atteinte palpébrale superficielle.', 'L’œdème et les collections peuvent comprimer les structures orbitaires et compromettre la fonction du nerf optique. Les muscles et tissus voisins inflammatoires rendent le regard douloureux ou limité.', 'Les complications comprennent abcès sous-périosté ou orbitaire, thrombose du sinus caverneux et infection intracrânienne. La classification de Chandler décrit différents tableaux anatomiques ; elle n’est pas une succession obligatoire chez chaque patient.', 'La source sinusienne, cutanée, dentaire ou traumatique modifie la microbiologie attendue. Le traitement doit atteindre le foyer et être associé au contrôle d’une collection lorsqu’il est nécessaire.'),(9,37,43))
l.add('La démarche reconnaît les {menaces immédiates}. Une altération de la vision ou un signe neurologique accélère encore la prise en charge. L’absence d’alarme complète ne justifie pas un essai oral ambulatoire devant une suspicion orbitaire.',table(['Constat','Menace','Action'],[['Vision diminuée, couleurs altérées ou déficit pupillaire afférent','Souffrance du nerf optique.','Ophtalmologie et prise en charge hospitalière immédiates.'],['Œil très tendu, douleur intense, exophtalmie importante','Compression ou collection menaçante.','Évaluation urgente pour décompression ou drainage.'],['Céphalées sévères, vomissements, somnolence, convulsion ou déficit focal','Extension intracrânienne.','Imagerie et équipes spécialisées urgentes.'],['Instabilité circulatoire ou altération majeure de l’état général','Sepsis.','Réanimation et antibiothérapie urgente ; appel 144 si nécessaire.'],['Œil non examinable','Atteinte profonde non exclue.','Ne pas classer en forme superficielle.']]),(9,37,43))
l.add('L’{anamnèse} est courte lorsque l’urgence domine. Elle recherche le foyer, la progression et les traitements déjà administrés. Les proches peuvent aider à repérer un changement visuel ou comportemental chez l’enfant.',steps('Préciser début, vitesse d’aggravation, fièvre et douleur.', 'Demander vision floue, diplopie, douleur aux mouvements, céphalées et vomissements.', 'Rechercher sinusite, foyer dentaire, traumatisme, chirurgie, corps étranger ou infection lacrymale.', 'Recueillir poids, terrain, immunodépression, statut vaccinal et traitements.', 'Décrire précisément toute allergie médicamenteuse et les antibiotiques déjà reçus.', 'Ne pas retarder les gestes urgents pour compléter une anamnèse exhaustive.'),(9,37,43,45))
l.add('L’{examen initial et répété} suit la vision, la motilité et l’état neurologique. Les résultats sont datés pour détecter une évolution. Une simple mesure du gonflement palpébral ne suffit pas.',paras('Évaluer paramètres vitaux, vigilance et perfusion. Mesurer l’acuité de chaque œil et rechercher une asymétrie pupillaire ou un déficit afférent. Comparer perception des couleurs et champ visuel selon la coopération.', 'Décrire position du globe, exophtalmie, chémosis, douleur et limitation des mouvements. Le spécialiste examine aussi les autres structures oculaires, dont le fond d’œil lorsque possible.', 'Examiner les sinus et territoires dentaires ou cutanés selon le contexte. Rechercher méningisme et déficit neurologique. L’examen de l’enfant s’adapte à l’âge sans forcer une interprétation rassurante.', 'Consigner toute limite liée à la douleur, à l’âge ou à l’œdème. La décision d’imagerie et de prise en charge tient compte de cette incertitude. Les examens sont répétés pendant le traitement.'),(9,37,42,43))
l.add('L’{approche syndromique} distingue infection profonde et autres causes d’exophtalmie ou d’œdème. Le contexte infectieux soutient l’hypothèse sans la prouver seul. Les urgences alternatives gardent leur propre parcours.',table(['Hypothèse','Indices','Suite'],[['Cellulite préseptale','Œil examinable, vision et motilité normales.','Parcours de la monographie précédente selon gravité.'],['Cellulite orbitaire','Signes orbitaires avec contexte infectieux.','Hospitalisation urgente.'],['Thrombose du sinus caverneux','Signes neurologiques, atteinte de plusieurs nerfs ou bilatéralisation.','Imagerie et traitement multidisciplinaire.'],['Inflammation orbitaire non infectieuse','Présentation et bilan spécifiques.','Ne pas commencer un corticoïde avant d’avoir évalué l’infection.'],['Tumeur orbitaire','Évolution atypique ou masse.','Imagerie et diagnostic spécialisé.'],['Infection fongique invasive','Immunodépression, diabète à risque, signes sévères ou atypiques.','Avis infectiologique et chirurgical immédiat.']]),(9,42,43))
l.add('Le {diagnostic positif} associe une suspicion clinique postseptale et l’exploration de son étendue. Il ne nécessite pas une baisse visuelle déjà installée. Le traitement urgent peut commencer avant une confirmation microbiologique.',paras('Motilité douloureuse ou limitée, exophtalmie et signes visuels orientent la localisation. Certains patients n’ont qu’une partie de ces signes. Les paramètres inflammatoires ne constituent pas un test d’exclusion.', 'L’imagerie distingue infiltration, collection, foyer sinusien et complications. La localisation et la taille d’un abcès contribuent à la décision opératoire, mais ne remplacent pas l’état visuel et l’évolution.', 'Les prélèvements aident à cibler l’antibiothérapie. Un prélèvement conjonctival ne représente pas nécessairement le germe du foyer profond ; une culture de drainage est plus directement informative lorsque le drainage est indiqué.'),(9,43))
l.add('Les {examens complémentaires} sont organisés avec les spécialistes. L’imagerie recherche une collection et une extension. Les prélèvements utiles sont réalisés sans retarder le traitement d’une infection menaçante.', '<h3>9.a — Imagerie</h3>'+paras('La TDM avec contraste des orbites et sinus est un examen majeur dans le parcours urgent. Une extension cérébrale ou veineuse peut nécessiter une exploration complémentaire, notamment une IRM selon les spécialistes. Ne pas retarder le traitement pour attendre un examen moins disponible.')+'<h3>9.b — Première intention</h3>'+paras('Numération, marqueurs inflammatoires, fonction rénale et hémocultures selon gravité. La fonction rénale sert aussi au choix du contraste et de la posologie. Un bilan de sepsis est adapté à l’état général.')+'<h3>9.c — Prélèvements ciblés</h3>'+paras('Prélever un foyer drainé ou exploré lorsqu’indiqué. Interpréter les cultures et antécédents de résistance avec l’infectiologie. Une culture négative après antibiotiques n’exclut pas une infection.')+'<h3>9.d — Réévaluation</h3>'+paras('Répéter l’imagerie si aggravation ou évolution insuffisante selon l’équipe. Certains parcours pédiatriques permettent de différer une imagerie chez des enfants sélectionnés sous surveillance spécialisée. Cette possibilité ne s’applique pas comme consigne d’attente à domicile ni en cas de menace visuelle, neurologique ou d’examen impossible.'),(9,43))
l.add('L’{arbre décisionnel} débute par l’hospitalisation et la protection des fonctions vitales et visuelles. Le traitement et l’exploration avancent ensemble. La nécessité de drainage est réévaluée avec l’évolution.',steps('Suspicion postseptale : admission urgente et avis ophtalmologique/ORL.', 'Instabilité ou signe neurologique : réanimation, infectiologie et autres équipes selon besoin.', 'Réaliser les prélèvements utiles et commencer rapidement l’antibiothérapie intraveineuse adaptée.', 'Organiser l’imagerie pour étendue, collection et foyer sans retarder le traitement urgent.', 'Si menace visuelle, collection préoccupante ou échec, discuter drainage ou autre contrôle du foyer sans attendre un délai arbitraire.', 'Adapter aux cultures, à l’évolution et à la fonction rénale ; décider du relais et de la durée avec les spécialistes.'),(9,37,43,44))
l.add('La {prise en charge en Suisse} est hospitalière et multidisciplinaire. Elle associe une antibiothérapie systémique, le contrôle du foyer et une surveillance visuelle répétée. Un collyre ou le seul schéma oral préseptal ne répond pas à cette situation.', '<h3>11.A — But</h3>'+paras('Préserver la vision, contrôler l’infection et éviter les complications intracrâniennes. La baisse visuelle, une collection et le sepsis imposent une action rapide.')+'<h3>11.B — Antibiotiques et foyer</h3>'+paras('Le choix probabiliste couvre les germes attendus selon foyer, terrain, vaccination et résistances locales. L’amoxicilline–clavulanate intraveineuse est une option documentée dans certains parcours sélectionnés. La spécialité suisse suivante fournit les doses et restrictions de produit :')+med+paras('Une évolution rapide, une atteinte du nerf optique ou une extension intracrânienne demande un spectre et une pénétration tissulaire adaptés. Les recommandations pédiatriques citées décrivent alors des associations spécialisées, comprenant notamment une céphalosporine adaptée, une couverture antistaphylococcique et des anaérobies selon le contexte. Aucun schéma chiffré étranger de cette association n’est transposé ici.', 'Une allergie sévère, un SARM ou une suspicion fongique nécessite un autre choix avec l’infectiologie. Les préparations et doses doivent être vérifiées dans leurs notices suisses avant prescription. La présence de clavulanate ne garantit pas toutes ces couvertures.', 'L’ophtalmologie et l’ORL évaluent le drainage d’un abcès et le traitement du foyer sinusien ou dentaire. Une petite collection peut parfois relever d’une surveillance hospitalière rapprochée ; une menace visuelle ou une mauvaise réponse modifie cette décision. Pas de seuil de taille universel inventé.', 'Les corticoïdes systémiques ne sont pas systématiques : les données restent insuffisantes pour une utilisation de routine. Les soins nasaux et autres adjuvants se décident selon les équipes. Une décompression urgente, si nécessaire, relève de professionnels formés.')+'<h3>11.C — Surveillance</h3>'+paras('Répéter acuité, pupilles, motilité, douleur, exophtalmie et examen neurologique selon la gravité. Le parcours BSAC propose des observations oculaires et neurologiques toutes les quatre heures et une réévaluation ophtalmologique quotidienne pendant l’intraveineux. Une détérioration impose une action immédiate entre ces contrôles.', 'Contrôler paramètres vitaux, tolérance, numération et fonctions rénale/hépatique selon les médicaments. Réévaluer les cultures et le foyer. Ne pas attribuer une vision plus faible à la seule fatigue sans examen.')+'<h3>11.D — Évolution et relais</h3>'+paras('Le relais oral suppose une amélioration clinique et une décision spécialisée. Des guides citent dix à quatorze jours au total pour certaines formes non compliquées ; abcès ou extension intracrânienne peuvent nécessiter plus longtemps. La durée n’est pas déterminée par le seul nombre de jours de fièvre.', 'Avant la sortie, documenter la fonction visuelle et organiser contrôle et consignes de retour. Une séquelle visuelle ou motrice nécessite son suivi. L’amélioration de la paupière seule ne suffit pas à conclure à la guérison.'),(9,37,42,43,44,45))
l.add('La {prévention secondaire} traite le foyer et organise le suivi. Elle évite une répétition d’antibiotiques sans réévaluation. Les proches doivent reconnaître les signes imposant un retour urgent.',paras('Contrôler le foyer sinusien, dentaire, cutané ou lacrymal identifié. Rechercher un corps étranger si le contexte le suggère. Vérifier vaccination et facteurs favorisants avec les équipes habituelles.', 'Expliquer les médicaments, la durée prescrite, les contrôles et la conduite devant une intolérance. Douleur aux mouvements, vision modifiée, diplopie, fièvre persistante ou signes neurologiques imposent un nouvel examen.', 'Une corticothérapie ancienne ou des gouttes restantes ne sont pas une réponse à une récidive. Un antécédent d’infection orbitaire doit être signalé lors d’un épisode ultérieur.'),(9,37,43))
l.add('Les {points clés} associent urgence, localisation et réévaluation. La vision peut être menacée avant une altération générale majeure. Les doses officielles ne suffisent pas à décider du spectre ou du drainage.',steps('Toute suspicion orbitaire impose le parcours hospitalier.', 'Un œil non examinable n’est pas un œil normal.', 'L’imagerie ne retarde pas l’antibiothérapie urgente.', 'Une collection ne se traite pas uniquement sur sa taille : vision, siège et évolution comptent.', 'Les formulations intraveineuses ont des rapports de composants différents.', 'Une atteinte rénale pédiatrique change exceptionnellement la présentation requise selon la notice.'),(9,43,45))
l.quiz([('Quelle structure sépare localisation préseptale et postseptale ?','Le septum orbitaire.'),('Tous les signes orbitaires sont-ils nécessaires pour agir ?','Non. Une suspicion suffisante ou un examen impossible impose une évaluation urgente.'),('Quelle douleur est particulièrement préoccupante ?','La douleur provoquée par les mouvements du globe.'),('Une vision normale au premier examen exclut-elle toute cellulite orbitaire ?','Non. Elle doit être documentée puis surveillée.'),('Quelle complication rechercher devant céphalée intense et somnolence ?','Une extension intracrânienne, parmi les urgences possibles.'),('L’absence de collection à l’imagerie rend-elle automatiquement le cas ambulatoire ?','Non. Une infection postseptale sans abcès peut nécessiter hospitalisation et surveillance.'),('Faut-il attendre les cultures pour traiter une infection menaçante ?','Non. Prélever sans retarder l’antibiothérapie urgente.'),('La pommade de l’orgelet peut-elle remplacer le traitement systémique ?','Non.'),('Le clavulanate garantit-il une activité sur le SARM ?','Non. Une couverture spécifique peut être nécessaire selon le contexte.'),('Que signifie 55 mg/kg dans la notice intraveineuse citée ?','La somme de 50 mg/kg d’amoxicilline et 5 mg/kg de clavulanate par administration dans le schéma concerné.'),('Le flacon 2200 mg peut-il être injecté en bolus ?','Non. Il est destiné à la perfusion selon la notice.'),('Quelle exception concerne l’enfant insuffisant rénal de plus de quatre semaines ?','La notice demande la présentation 1000/200 mg au rapport 5:1, avec doses spécifiques et vérification pharmaceutique.'),('Les corticoïdes systémiques sont-ils systématiques ?','Non. Les données ne justifient pas une utilisation de routine.'),('Une petite collection exclut-elle toute chirurgie ?','Non. La vision, le siège, l’évolution et l’avis spécialisé guident la décision.')],(9,43,44,45))
l.write()
